# -segaddr list for linking the kernel into the kc27 fileset KC (generated by k27/kc27-layout.py; offsets from the KC header page)
KB=0xfffffff007004000
echo -n "-Wl,-rename_section,__TEXT,__cstring,__TEXT_EXEC,__cstring "
a() { printf -- "-Wl,-segaddr,%s,0x%x " "$1" $((KB + $2)); }
{
a __TEXT 0x4000; a __DATA_CONST 0x810000; a __LASTDATA_CONST 0x9f0000; a __TEXT_EXEC 0x2dcc000; a __KLD 0x3834000; a __LAST 0x3840000; a __KLDDATA 0x3a54000; a __DATA 0x3a5c000; a __BOOTDATA 0x3bc0000; a __PRELINK_TEXT 0x3844000;
o=0x3ca4000; for n in __PRELINK_DATA __PRELINK_INFO __PLK_TEXT_EXEC __PLK_DATA_CONST __PLK_LLVM_COV __PLK_LINKEDIT; do a $n $o; o=$((o+0x4000)); done
a __LINKINFO 0x3e00000
} | sed 's/ $//'
